import React, { useEffect, useMemo, useRef, useState } from 'react';
import {
  Box,
  Grid,
  IconButton,
  InputAdornment,
  Paper,
  Skeleton,
  Stack,
  styled,
  TextField,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import ArrowBackIosNewIcon from '@mui/icons-material/ArrowBackIosNew';
import ArrowForwardIosIcon from '@mui/icons-material/ArrowForwardIos';
import SearchIcon from '@mui/icons-material/Search';
import useScanDetection from 'use-scan-detection-react18';
import { useGetAllProductQuery } from '../../posApi';
import { useAppDispatch } from '../../../store/hooks';
import { addItem } from '../store/BasketSlice';
import { getPriceFormatWithoutCurrency } from '../../../core/utils';
import { IProductData, IProduct } from '../../../core/Interface/product.interface';
import {
  IPreOrderJewelleryBasketItem,
} from '../../../core/Interface/preOrderJewellery.interface';
import Kgpopup from './Kgpopup';

/* ── colour tokens ───────────────────────────────────────────────────────── */
const TEAL = '#0F8B8D';
const NAVY = '#0F1D4D';
const CAT_INACTIVE = 'linear-gradient(135deg, #dbeafe 0%, #bfdbfe 100%)';
const CAT_ACTIVE   = `linear-gradient(135deg, ${NAVY} 0%, #1E3A8A 100%)`;
const NAV_BG       = `linear-gradient(135deg, ${NAVY} 0%, #1E3A8A 100%)`;
const PROD_BG      = 'linear-gradient(145deg, #eef2ff 0%, #e0e7ff 100%)';
const PROD_BG_HVR  = 'linear-gradient(145deg, #dde5ff 0%, #c7d6ff 100%)';
const PROD_BORDER  = 'rgba(99, 120, 220, 0.18)';

/* ── pagination settings ─────────────────────────────────────────────────── */
const CAT_PER_ROW  = 7;   // category tiles per row (+ 1 nav tile = 8 total per row)
const PROD_PER_PAGE = 15; // product tiles per page (+ 1 nav tile = 16 total per row group)

/* ── styled tile ─────────────────────────────────────────────────────────── */
const Tile = styled(Paper)({
  alignItems: 'center',
  borderRadius: '10px',
  boxShadow: 'none',
  cursor: 'pointer',
  display: 'flex',
  height: 'var(--tile-h)',
  justifyContent: 'center',
  textAlign: 'center',
  verticalAlign: 'middle',
});

/* ── component ───────────────────────────────────────────────────────────── */
const OrderRightPanel: React.FC = () => {
  const dispatch = useAppDispatch();
  const [selectedCat, setSelectedCat] = useState('');
  const [catPage, setCatPage] = useState(0);
  const [prodPage, setProdPage] = useState(0);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedProduct, setSelectedProduct] = useState<IProductData | null>(null);
  const [openPopup, setOpenPopup] = useState(false);
  const searchRef = useRef<HTMLInputElement>(null);

  const { data, isLoading } = useGetAllProductQuery({
    pageIndex: 0,
    pageSize: 1000,
    searchText: '',
  });

  const productData = useMemo(() => data?.data as IProduct, [data?.data]);

  /* group by category */
  const categoryMemo = useMemo(() => {
    const grouped: Record<string, IProductData[]> = {};
    if (productData?.records) {
      productData.records.forEach((p) => {
        if (!grouped[p.categoryName]) grouped[p.categoryName] = [];
        grouped[p.categoryName].push(p);
      });
    }
    return grouped;
  }, [productData]);

  const allCategories = useMemo(
    () =>
      Object.keys(categoryMemo).sort((a, b) =>
        a.toLowerCase().localeCompare(b.toLowerCase())
      ),
    [categoryMemo]
  );

  /* category pagination */
  const catPageData = useMemo(() => {
    const start = catPage * CAT_PER_ROW;
    return allCategories.slice(start, start + CAT_PER_ROW);
  }, [catPage, allCategories]);

  const catTotalPages = Math.ceil(allCategories.length / CAT_PER_ROW);

  /* filtered products */
  const filteredProducts = useMemo(() => {
    let base = selectedCat
      ? (categoryMemo[selectedCat] ?? [])
      : (productData?.records ?? []);
    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase();
      base = base.filter(
        (p) =>
          p.name.toLowerCase().includes(q) || p.code.toLowerCase().includes(q)
      );
    }
    return base.filter((p) => p.isEnabled);
  }, [selectedCat, categoryMemo, productData, searchQuery]);

  /* product pagination */
  const prodPageData = useMemo(() => {
    const start = prodPage * PROD_PER_PAGE;
    return filteredProducts.slice(start, start + PROD_PER_PAGE);
  }, [prodPage, filteredProducts]);

  const prodTotalPages = Math.ceil(filteredProducts.length / PROD_PER_PAGE);

  /* reset product page when category or search changes */
  useEffect(() => {
    setProdPage(0);
  }, [selectedCat, searchQuery]);

  /* focus search on mount */
  useEffect(() => {
    if (searchRef.current) searchRef.current.focus();
  }, []);

  /* barcode scan → add item directly */
  useScanDetection({
    onComplete: (code) => {
      const clean = code.replace('Shift', '');
      const matches = productData?.records?.filter((p) => p.code.includes(clean));
      if (matches?.length === 1) {
        const basketItem: IPreOrderJewelleryBasketItem = {
          ...matches[0],
          amount: 0,
          count: 1,
        };
        dispatch(addItem(basketItem));
        setSearchQuery('');
      }
    },
  });

  const handleProductClick = (item: IProductData) => {
    setSelectedProduct(item);
    setOpenPopup(true);
  };

  const handleAddToBasket = (
    calculatedValue: number | null,
    inputCount: number,
    goldData?: {
      goldWeightQty: number;
      goldWasteQty: number;
      goldCarrot: string;
      makingCharge: number;
      goldPrice8g: number;
    }
  ) => {
    if (selectedProduct && calculatedValue !== null) {
      const variantId = `${selectedProduct.id}__v${Math.floor(Math.random() * 20) + 10}`;
      const basketItem: IPreOrderJewelleryBasketItem = {
        ...selectedProduct,
        amount: 0,
        calculatedUnitPrice: calculatedValue,
        count: inputCount || 1,
        goldCarrot: goldData?.goldCarrot ?? '22K',
        goldPrice8g: goldData?.goldPrice8g ?? 0,
        goldWasteQty: goldData?.goldWasteQty ?? 0,
        goldWeightQty: goldData?.goldWeightQty ?? 0,
        id: variantId,
        makingCharge: goldData?.makingCharge ?? 0,
        unitPrice: calculatedValue,
      };
      dispatch(addItem(basketItem));
      setOpenPopup(false);
      setSelectedProduct(null);
    }
  };

  return (
    <Box
      sx={{
        '--tile-h': 'calc((100vh - 210px) / 7)',
        display: 'flex',
        flexDirection: 'column',
        gap: '6px',
        height: 'calc(100vh - 96px)',
        left: 'calc(33.333% + 4px)',
        overflow: 'hidden',
        pb: '8px',
        pt: '4px',
        position: 'fixed',
        right: '4px',
      }}
    >
      {/* ── Search bar ───────────────────────────────────────────── */}
      <Box sx={{ flex: '0 0 auto' }}>
        <TextField
          InputProps={{
            startAdornment: (
              <InputAdornment position="start">
                <SearchIcon sx={{ color: alpha(NAVY, 0.35), fontSize: 18 }} />
              </InputAdornment>
            ),
          }}
          autoComplete="off"
          fullWidth
          inputRef={searchRef}
          onChange={(e) => setSearchQuery(e.target.value)}
          placeholder="Search product name or code…"
          size="small"
          sx={{
            '& .MuiOutlinedInput-root': {
              '& fieldset': { borderColor: alpha(NAVY, 0.12) },
              '&.Mui-focused fieldset': { borderColor: TEAL },
              '&:hover fieldset': { borderColor: alpha(TEAL, 0.45) },
              backgroundColor: '#fff',
              borderRadius: '10px',
            },
          }}
          value={searchQuery}
        />
      </Box>

      {/* ── Category tiles ───────────────────────────────────────── */}
      <Box sx={{ flex: '0 0 auto' }}>
        <Grid
          container
          spacing={1}
        >
          {/* ALL tile */}
          <Grid
            item
            md={1.5}
            sm={2}
            xs={2}
          >
            <Tile
              onClick={() => setSelectedCat('')}
              sx={{
                background: selectedCat === '' ? CAT_ACTIVE : CAT_INACTIVE,
                border: selectedCat === '' ? '2px solid #99f6e4' : '2px solid transparent',
                boxShadow: selectedCat === '' ? '0 4px 14px rgba(20,30,85,0.35)' : 'none',
              }}
            >
              <Typography
                sx={{
                  color: selectedCat === '' ? '#fff' : NAVY,
                  fontSize: 11,
                  fontWeight: 700,
                  letterSpacing: '0.3px',
                }}
              >
                ALL
              </Typography>
            </Tile>
          </Grid>

          {/* Category tiles */}
          {!isLoading &&
            catPageData.map((cat) => (
              <Grid
                item
                key={`cat-${cat}`}
                md={1.5}
                sm={2}
                xs={2}
              >
                <Tile
                  onClick={() => setSelectedCat(selectedCat === cat ? '' : cat)}
                  sx={{
                    background: selectedCat === cat ? CAT_ACTIVE : CAT_INACTIVE,
                    border:
                      selectedCat === cat
                        ? '2px solid #99f6e4'
                        : '2px solid transparent',
                    boxShadow:
                      selectedCat === cat
                        ? '0 4px 14px rgba(20,30,85,0.35)'
                        : 'none',
                  }}
                >
                  <Typography
                    sx={{
                      color: selectedCat === cat ? '#fff' : NAVY,
                      fontSize: 11,
                      fontWeight: 700,
                      letterSpacing: '0.3px',
                      lineHeight: 1.2,
                      px: 0.5,
                      textAlign: 'center',
                    }}
                  >
                    {cat}
                  </Typography>
                </Tile>
              </Grid>
            ))}

          {/* Filler tiles */}
          {!isLoading &&
            catPageData.length < CAT_PER_ROW &&
            Array.from({
              length: CAT_PER_ROW - catPageData.length,
            }).map((_, k) => (
              <Grid
                item
                key={`cat-fill-${k}`}
                md={1.5}
                sm={2}
                xs={2}
              >
                <Tile
                  sx={{
                    background: 'rgba(148,163,184,0.12)',
                    boxShadow: 'none',
                    cursor: 'default',
                  }}
                />
              </Grid>
            ))}

          {/* Category nav arrows */}
          {!isLoading && (
            <Grid
              item
              md={1.5}
              sm={2}
              xs={2}
            >
              <Tile sx={{ background: NAV_BG, cursor: 'default' }}>
                <Grid container>
                  <Grid
                    item
                    xs={6}
                  >
                    <IconButton
                      disabled={catPage <= 0}
                      onClick={() => setCatPage((p) => p - 1)}
                      size="small"
                      sx={{
                        '&:disabled': { color: 'rgba(255,255,255,0.3)' },
                        color: '#fff',
                      }}
                    >
                      <ArrowBackIosNewIcon sx={{ fontSize: 20 }} />
                    </IconButton>
                  </Grid>
                  <Grid
                    item
                    xs={6}
                  >
                    <IconButton
                      disabled={catPage >= catTotalPages - 1}
                      onClick={() => setCatPage((p) => p + 1)}
                      size="small"
                      sx={{
                        '&:disabled': { color: 'rgba(255,255,255,0.3)' },
                        color: '#fff',
                      }}
                    >
                      <ArrowForwardIosIcon sx={{ fontSize: 20 }} />
                    </IconButton>
                  </Grid>
                </Grid>
              </Tile>
            </Grid>
          )}

          {/* Loading skeleton for categories */}
          {isLoading &&
            Array.from({ length: CAT_PER_ROW + 1 }).map((_, i) => (
              <Grid
                item
                key={`cat-skel-${i}`}
                md={1.5}
                sm={2}
                xs={2}
              >
                <Skeleton
                  height="var(--tile-h)"
                  sx={{ borderRadius: '10px' }}
                  variant="rectangular"
                />
              </Grid>
            ))}
        </Grid>
      </Box>

      {/* ── Product tiles ─────────────────────────────────────────── */}
      <Box sx={{ flex: 1, overflow: 'hidden' }}>
        <Grid
          container
          spacing={1}
        >
          {/* Product tiles */}
          {!isLoading &&
            prodPageData.map((p) => (
              <Grid
                item
                key={p.id}
                md={1.5}
                sm={2}
                xs={2}
              >
                <Tile
                  onClick={() => handleProductClick(p)}
                  sx={{
                    '&:hover': {
                      background: PROD_BG_HVR,
                      boxShadow: `0 3px 10px ${alpha(NAVY, 0.12)}`,
                    },
                    background: PROD_BG,
                    border: `1px solid ${PROD_BORDER}`,
                    transition: 'background 0.15s, box-shadow 0.15s',
                  }}
                >
                  <Stack
                    alignItems="center"
                    direction="column"
                    sx={{ px: 0.5 }}
                  >
                    <Typography
                      sx={{
                        color: NAVY,
                        fontSize: 11,
                        fontWeight: 700,
                        lineHeight: 1.2,
                        mb: '2px',
                        textAlign: 'center',
                      }}
                    >
                      {p.name.length > 16
                        ? `${p.name.substring(0, 16)}…`
                        : p.name}
                    </Typography>
                    <Typography
                      sx={{
                        color: TEAL,
                        fontSize: 11,
                        fontVariantNumeric: 'tabular-nums',
                        fontWeight: 800,
                      }}
                    >
                      {getPriceFormatWithoutCurrency(p.unitPrice)}
                    </Typography>
                  </Stack>
                </Tile>
              </Grid>
            ))}

          {/* Filler tiles for incomplete last row */}
          {!isLoading &&
            prodPageData.length < PROD_PER_PAGE &&
            Array.from({
              length: PROD_PER_PAGE - prodPageData.length,
            }).map((_, k) => (
              <Grid
                item
                key={`prod-fill-${k}`}
                md={1.5}
                sm={2}
                xs={2}
              >
                <Tile
                  sx={{
                    background: '#eef2ff',
                    border: `1px solid ${PROD_BORDER}`,
                    boxShadow: 'none',
                    cursor: 'default',
                    opacity: 0.35,
                  }}
                />
              </Grid>
            ))}

          {/* Product nav arrows */}
          {!isLoading && (
            <Grid
              item
              md={1.5}
              sm={2}
              xs={2}
            >
              <Tile sx={{ background: NAV_BG, cursor: 'default' }}>
                <Grid container>
                  <Grid
                    item
                    xs={6}
                  >
                    <IconButton
                      disabled={prodPage <= 0}
                      onClick={() => setProdPage((p) => p - 1)}
                      size="small"
                      sx={{
                        '&:disabled': { color: 'rgba(255,255,255,0.3)' },
                        color: '#fff',
                      }}
                    >
                      <ArrowBackIosNewIcon sx={{ fontSize: 22 }} />
                    </IconButton>
                  </Grid>
                  <Grid
                    item
                    xs={6}
                  >
                    <IconButton
                      disabled={prodPage >= prodTotalPages - 1}
                      onClick={() => setProdPage((p) => p + 1)}
                      size="small"
                      sx={{
                        '&:disabled': { color: 'rgba(255,255,255,0.3)' },
                        color: '#fff',
                      }}
                    >
                      <ArrowForwardIosIcon sx={{ fontSize: 22 }} />
                    </IconButton>
                  </Grid>
                </Grid>
              </Tile>
            </Grid>
          )}

          {/* Loading skeletons for products */}
          {isLoading &&
            Array.from({ length: PROD_PER_PAGE + 1 }).map((_, i) => (
              <Grid
                item
                key={`prod-skel-${i}`}
                md={1.5}
                sm={2}
                xs={2}
              >
                <Skeleton
                  height="var(--tile-h)"
                  sx={{ borderRadius: '10px' }}
                  variant="rectangular"
                />
              </Grid>
            ))}
        </Grid>
      </Box>

      {/* ── Kgpopup ──────────────────────────────────────────────── */}
      {selectedProduct && openPopup && (
        <Kgpopup
          handleAdd={handleAddToBasket}
          handleCloseAlert={() => {
            setOpenPopup(false);
            setSelectedProduct(null);
          }}
          open={openPopup}
          product={selectedProduct}
        />
      )}
    </Box>
  );
};

export default React.memo(OrderRightPanel);
