import React, { useMemo, useState } from 'react';
import {
  Box,
  Button,
  Chip,
  CircularProgress,
  Divider,
  Grid,
  IconButton,
  Tooltip,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import PersonAddAlt1Icon from '@mui/icons-material/PersonAddAlt1';
import PersonIcon from '@mui/icons-material/Person';
import DeleteOutlineIcon from '@mui/icons-material/DeleteOutline';
import { useSelector } from 'react-redux';
import { useAppDispatch } from '../../../store/hooks';
import { appColors, HEADER_GRADIENT } from '../../../theme/appColors';
import {
  selectBasketItems,
  addCustomer as selectCustomer,
  finalSummaryStare as selectFinalSummary,
  selectPaymentMethod,
} from '../store/BasketSelector';
import {
  removeBasket,
  removeItem,
  addFinalSummaryState,
  editBasket,
} from '../store/BasketSlice';
import useSales from '../useSales';
import OrderCustomerModal from './OrderCustomerModal';
import SalesDiscount from './SalesDiscount';
import Kgpopup from './Kgpopup';
import { getPriceFormatWithoutCurrency, calculateFontSize } from '../../../core/utils';
import {
  IPreOrderJewelleryBasketItem,
  IPreOrderJewelleryInvoice,
} from '../../../core/Interface/preOrderJewellery.interface';
import { useGetUserQuery, useOrderJewelleryMutation } from '../../posApi';
import { PreOrderInvoice } from './Invoice';
import { useReactToPrint } from 'react-to-print';
import { useNotifier } from '../../../core/Notifier';
import { IUserInfo } from '../../../core/Interface/user.interface';
import store from '../../../store';

const TEAL = '#0F8B8D';
const NAVY = '#0F1D4D';

/* ── helpers ────────────────────────────────────────────────────────────── */

const ColHeader: React.FC<{ label: string; align?: 'left' | 'right' | 'center' }> = ({
  label,
  align = 'right',
}) => (
  <Typography
    align={align}
    sx={{
      color: 'rgba(255,255,255,0.8)',
      fontSize: 10,
      fontWeight: 700,
      letterSpacing: '0.5px',
      textTransform: 'uppercase',
    }}
  >
    {label}
  </Typography>
);

const SummaryRow: React.FC<{ label: string; value: string; large?: boolean }> = ({
  label,
  value,
  large,
}) => (
  <Grid
    container
    sx={{ py: '3px' }}
  >
    <Grid
      item
      xs={6}
    >
      <Typography
        sx={{
          color: appColors.white,
          fontSize: 12,
          fontWeight: 600,
          letterSpacing: '0.4px',
          textTransform: 'uppercase',
        }}
      >
        {label}
      </Typography>
    </Grid>
    <Grid
      item
      xs={6}
    >
      <Typography
        align="right"
        sx={{
          color: appColors.white,
          fontSize: large ? 16 : 12,
          fontVariantNumeric: 'tabular-nums',
          fontWeight: large ? 900 : 600,
          lineHeight: 1,
        }}
      >
        {value}
      </Typography>
    </Grid>
  </Grid>
);

/* ── empty invoice (for print state init) ───────────────────────────────── */

const EMPTY_INVOICE: IPreOrderJewelleryInvoice = {
  balance: 0,
  branch: {
    code: '',
    companyId: '',
    createdBy: '',
    createdDate: '',
    email: '',
    footerText1: '',
    footerText2: '',
    footerText3: '',
    headerText1: '',
    headerText2: '',
    headerText3: '',
    id: '',
    imageUrl: '',
    isDeleted: false,
    logo: '',
    mobile: '',
    name: '',
    noticeText: '',
    printPaperSize: '',
    reloadLoginMobile: '',
    reloadLoginPassword: '',
    updatedBy: null,
    updatedDate: null,
  },
  createdBy: '',
  customerName: { mobile: '', name: '' },
  dateTime: '',
  deliveryDateTime: '',
  discount: 0,
  isDiscountPercentage: false,
  items: [],
  orderNo: '',
  received: 0,
  sn: 0,
  subTotal: 0,
};

/* ── component ───────────────────────────────────────────────────────────── */

const OrderLeftPanel: React.FC = () => {
  const dispatch = useAppDispatch();
  const { calculateSummary, salesDetails } = useSales();
  const items = useSelector(selectBasketItems);
  const customer = useSelector(selectCustomer);
  const paymentStatus = useSelector(selectFinalSummary);

  const [openAddMobile, setOpenAddMobile] = useState(false);
  const [openDiscount, setOpenDiscount] = useState(false);
  const [selectedItem, setSelectedItem] = useState<IPreOrderJewelleryBasketItem | null>(null);
  const [openEditPopup, setOpenEditPopup] = useState(false);

  const { showErrorMessage, showMessage } = useNotifier();
  const [saveSales, { isLoading }] = useOrderJewelleryMutation();
  const { data: companyData } = useGetUserQuery();

  const printPaperSizeInPixel = useMemo(() => {
    if (companyData?.data) {
      const ud = companyData.data as IUserInfo;
      if (ud.branch.printPaperSizeInPixel) return Number(ud.branch.printPaperSizeInPixel);
    }
    return 10;
  }, [companyData]);

  const currencyCode = useMemo(() => {
    if (companyData?.data) {
      const ud = companyData.data as IUserInfo;
      if (ud.company.currencyCode) return ud.company.currencyCode;
    }
    return '';
  }, [companyData]);

  const [invoiceData, setInvoiceData] = useState<IPreOrderJewelleryInvoice>(EMPTY_INVOICE);
  const componentRef = React.useRef<HTMLDivElement | null>(null);
  const handlePrint = useReactToPrint({ content: () => componentRef.current });

  const handlePay = async () => {
    try {
      const salesRes = await saveSales({
        ...salesDetails,
        paymentMethod: selectPaymentMethod(store.getState()),
      }).unwrap();
      if (!salesRes.status) {
        showErrorMessage(salesRes.message);
      } else {
        setInvoiceData(salesRes.data as IPreOrderJewelleryInvoice);
        showMessage(salesRes.message);
        setTimeout(() => handlePrint(), 200);
        dispatch(removeBasket());
      }
    } catch (error) {
      showErrorMessage((error as Error).message);
    }
  };

  const pay = async () => {
    if (!customer.mobile || !customer.customerName) {
      setOpenAddMobile(true);
      return;
    }
    if (!paymentStatus) {
      dispatch(addFinalSummaryState({ finalSummaryStare: true }));
      return;
    }
    if (salesDetails.balance < 0 && !salesDetails.mobile) return;
    if (salesDetails.items.length > 0) {
      try {
        await handlePay();
      } catch {
        showErrorMessage('Please check your data');
      }
    }
  };

  const handleEditAdd = (
    calculatedValue: number | null,
    inputCount: number,
    goldData?: {
      goldWeightQty: number;
      goldWasteQty: number;
      goldCarrot: string;
      makingCharge: number;
      goldPrice8g: number;
    }
  ) => {
    if (selectedItem && calculatedValue !== null) {
      dispatch(
        editBasket({
          ...selectedItem,
          calculatedUnitPrice: calculatedValue,
          count: inputCount || 1,
          goldCarrot: goldData?.goldCarrot ?? '22K',
          goldPrice8g: goldData?.goldPrice8g ?? 0,
          goldWasteQty: goldData?.goldWasteQty ?? 0,
          goldWeightQty: goldData?.goldWeightQty ?? 0,
          makingCharge: goldData?.makingCharge ?? 0,
          unitPrice: calculatedValue,
        })
      );
      setOpenEditPopup(false);
      setSelectedItem(null);
    }
  };

  const itemTotal = (item: IPreOrderJewelleryBasketItem) =>
    (item.goldWeightQty ?? 0) * ((item.goldPrice8g ?? 0) / 8) +
    (item.makingCharge ?? 0) +
    (item.goldWasteQty ?? 0) * ((item.goldPrice8g ?? 0) / 8);

  return (
    <Box
      sx={{
        backgroundColor: appColors.white,
        borderRadius: '12px',
        boxShadow: '0 4px 24px rgba(0,20,137,0.14)',
        display: 'flex',
        flexDirection: 'column',
        height: 'calc(100vh - 96px)',
        left: 4,
        overflow: 'hidden',
        position: 'fixed',
        width: '32%',
      }}
    >
      {/* ── Customer section ──────────────────────────────────────── */}
      <Box
        sx={{
          backgroundColor: appColors.white,
          borderBottom: `1px solid ${appColors.darkGray[10]}`,
          p: '10px 12px',
        }}
      >
        <Box
          sx={{
            alignItems: 'center',
            display: 'flex',
            justifyContent: 'space-between',
            gap: 1,
          }}
        >
          <Box sx={{ alignItems: 'center', display: 'flex', gap: 1 }}>
            <Box
              sx={{
                alignItems: 'center',
                background: customer.mobile ? alpha(TEAL, 0.1) : alpha(NAVY, 0.06),
                borderRadius: '8px',
                display: 'flex',
                height: 34,
                justifyContent: 'center',
                width: 34,
                flexShrink: 0,
              }}
            >
              <PersonIcon
                sx={{
                  color: customer.mobile ? TEAL : '#94A3B8',
                  fontSize: 18,
                }}
              />
            </Box>
            {customer.mobile ? (
              <Box>
                <Typography
                  sx={{
                    color: NAVY,
                    fontSize: 13,
                    fontWeight: 700,
                    lineHeight: 1.2,
                  }}
                >
                  {customer.customerName || customer.mobile}
                </Typography>
                <Typography sx={{ color: '#64748B', fontSize: 11, fontWeight: 500 }}>
                  {customer.mobile}
                  {customer.deliveryDateTime && (
                    <> · Delivery: {new Date(customer.deliveryDateTime).toLocaleDateString()}</>
                  )}
                </Typography>
              </Box>
            ) : (
              <Typography sx={{ color: '#94A3B8', fontSize: 13, fontWeight: 500 }}>
                No customer selected
              </Typography>
            )}
          </Box>

          <Tooltip title={customer.mobile ? 'Change customer' : 'Add customer'}>
            <IconButton
              onClick={() => setOpenAddMobile(true)}
              size="small"
              sx={{
                background: alpha(TEAL, 0.08),
                borderRadius: '8px',
                color: TEAL,
                flexShrink: 0,
                '&:hover': { background: alpha(TEAL, 0.16) },
              }}
            >
              <PersonAddAlt1Icon sx={{ fontSize: 18 }} />
            </IconButton>
          </Tooltip>
        </Box>
      </Box>

      {/* ── Column headers ────────────────────────────────────────── */}
      <Box sx={{ background: HEADER_GRADIENT, px: '12px', py: '8px' }}>
        <Grid
          container
          flexWrap="nowrap"
          spacing={1}
        >
          <Grid
            item
            xs={4}
          >
            <ColHeader
              align="left"
              label="Item"
            />
          </Grid>
          <Grid
            item
            xs={2}
          >
            <ColHeader label="Wt (g)" />
          </Grid>
          <Grid
            item
            xs={2}
          >
            <ColHeader label="Making" />
          </Grid>
          <Grid
            item
            xs={3}
          >
            <ColHeader label="Amount" />
          </Grid>
          <Grid
            item
            xs={1}
          >
            <ColHeader label="" />
          </Grid>
        </Grid>
      </Box>

      {/* ── Basket items (scrollable) ─────────────────────────────── */}
      <Box
        sx={{
          '&::-webkit-scrollbar': { width: '3px' },
          '&::-webkit-scrollbar-thumb': {
            backgroundColor: '#94a3b8',
            borderRadius: '2px',
          },
          backgroundColor: appColors.white,
          flex: 1,
          overflowY: 'auto',
          scrollbarWidth: 'thin',
        }}
      >
        {items.length === 0 ? (
          <Box
            sx={{
              alignItems: 'center',
              display: 'flex',
              height: '100%',
              justifyContent: 'center',
              opacity: 0.4,
            }}
          >
            <Typography sx={{ color: appColors.royalBlue[60], fontSize: 13 }}>
              No items added yet
            </Typography>
          </Box>
        ) : (
          <Box sx={{ p: '4px 8px 0 8px' }}>
            {items
              .slice()
              .reverse()
              .map((item) => {
                const total = itemTotal(item);
                return (
                  <Grid
                    alignItems="center"
                    container
                    flexWrap="nowrap"
                    key={item.id}
                    onClick={() => {
                      setSelectedItem(item);
                      setOpenEditPopup(true);
                    }}
                    spacing={1}
                    sx={{
                      '&:hover': { backgroundColor: appColors.reflexBlue[10] },
                      '&:last-child': { borderBottom: 'none' },
                      borderBottom: `1px solid ${appColors.darkGray[10]}`,
                      borderRadius: '6px',
                      cursor: 'pointer',
                      px: '4px',
                      py: '6px',
                      transition: 'background 0.15s',
                    }}
                  >
                    {/* Item name + qty chip */}
                    <Grid
                      item
                      xs={4}
                    >
                      <Box sx={{ alignItems: 'center', display: 'flex', gap: 0.5 }}>
                        <Chip
                          label={item.count}
                          size="small"
                          sx={{
                            '& .MuiChip-label': { px: '5px' },
                            backgroundColor: appColors.reflexBlue[100],
                            color: '#fff',
                            flexShrink: 0,
                            fontSize: 10,
                            fontWeight: 700,
                            height: 18,
                          }}
                        />
                        <Typography
                          sx={{
                            color: appColors.royalBlue[100],
                            fontSize: 12,
                            fontWeight: 500,
                            lineHeight: 1.2,
                            overflow: 'hidden',
                            textOverflow: 'ellipsis',
                            whiteSpace: 'nowrap',
                          }}
                        >
                          {item.name}
                        </Typography>
                      </Box>
                    </Grid>

                    {/* Gold weight */}
                    <Grid
                      item
                      xs={2}
                    >
                      <Typography
                        align="right"
                        sx={{
                          color: appColors.royalBlue[80],
                          fontSize: 12,
                          fontVariantNumeric: 'tabular-nums',
                        }}
                      >
                        {(item.goldWeightQty ?? 0).toFixed(2)}
                      </Typography>
                    </Grid>

                    {/* Making charge */}
                    <Grid
                      item
                      xs={2}
                    >
                      <Typography
                        align="right"
                        sx={{
                          color: appColors.royalBlue[80],
                          fontSize: 12,
                          fontVariantNumeric: 'tabular-nums',
                        }}
                      >
                        {getPriceFormatWithoutCurrency(item.makingCharge ?? 0)}
                      </Typography>
                    </Grid>

                    {/* Total amount */}
                    <Grid
                      item
                      xs={3}
                    >
                      <Typography
                        align="right"
                        sx={{
                          color: appColors.royalBlue[80],
                          fontSize: 12,
                          fontVariantNumeric: 'tabular-nums',
                        }}
                      >
                        {getPriceFormatWithoutCurrency(total)}
                      </Typography>
                    </Grid>

                    {/* Delete */}
                    <Grid
                      item
                      xs={1}
                    >
                      <IconButton
                        onClick={(e) => {
                          e.stopPropagation();
                          dispatch(removeItem(item.id));
                        }}
                        size="small"
                        sx={{
                          '&:hover': { background: alpha('#EF4444', 0.1) },
                          color: '#EF4444',
                          p: '3px',
                        }}
                      >
                        <DeleteOutlineIcon sx={{ fontSize: 15 }} />
                      </IconButton>
                    </Grid>
                  </Grid>
                );
              })}
          </Box>
        )}
      </Box>

      {/* ── Summary footer ────────────────────────────────────────── */}
      <Box
        sx={{
          background: HEADER_GRADIENT,
          pb: '12px',
          pt: '10px',
          px: '14px',
        }}
      >
        <SummaryRow
          label="Subtotal"
          value={getPriceFormatWithoutCurrency(calculateSummary.subTotal)}
        />
        <SummaryRow
          label="Discount"
          value={`- ${getPriceFormatWithoutCurrency(calculateSummary.discount)}`}
        />
        <Divider sx={{ borderColor: 'rgba(255,255,255,0.2)', my: '8px' }} />
        <Grid
          alignItems="center"
          container
        >
          <Grid
            item
            xs={5}
          >
            <Typography
              sx={{
                color: appColors.white,
                fontSize: 13,
                fontWeight: 800,
                letterSpacing: '0.6px',
                textTransform: 'uppercase',
              }}
            >
              Total
            </Typography>
            {currencyCode && (
              <Typography
                sx={{ color: alpha('#fff', 0.7), fontSize: 10, fontWeight: 500 }}
              >
                {currencyCode}
              </Typography>
            )}
          </Grid>
          <Grid
            item
            xs={7}
          >
            <Typography
              align="right"
              sx={{
                color: appColors.white,
                fontSize: 18,
                fontVariantNumeric: 'tabular-nums',
                fontWeight: 900,
                lineHeight: 1,
              }}
            >
              {getPriceFormatWithoutCurrency(calculateSummary.total)}
            </Typography>
          </Grid>
        </Grid>
      </Box>

      {/* ── Action buttons ────────────────────────────────────────── */}
      <Box
        sx={{
          backgroundColor: '#F8FAFC',
          borderTop: '1px solid #E2E8F0',
          display: 'flex',
          gap: 1,
          px: 2,
          py: 1.5,
        }}
      >
        <Button
          fullWidth
          onClick={() => dispatch(removeBasket())}
          sx={{
            '&:hover': {
              background: alpha('#EF4444', 0.04),
              borderColor: '#EF4444',
              color: '#EF4444',
            },
            borderColor: '#CBD5E1',
            borderRadius: '8px',
            color: '#64748B',
            fontSize: 13,
            fontWeight: 600,
            height: 38,
          }}
          variant="outlined"
        >
          Clear
        </Button>

        <Button
          fullWidth
          onClick={() => setOpenDiscount(true)}
          sx={{
            '&:hover': {
              background: alpha(TEAL, 0.04),
              borderColor: TEAL,
            },
            borderColor: alpha(TEAL, 0.45),
            borderRadius: '8px',
            color: TEAL,
            fontSize: 13,
            fontWeight: 600,
            height: 38,
          }}
          variant="outlined"
        >
          Discount
        </Button>

        <Button
          disabled={isLoading || items.length === 0}
          fullWidth
          onClick={pay}
          startIcon={isLoading ? <CircularProgress size={14} sx={{ color: 'inherit' }} /> : undefined}
          sx={{
            '&.Mui-disabled': { background: '#CBD5E1', color: '#94A3B8' },
            '&:hover': {
              background: `linear-gradient(135deg, #0c7a7c 0%, #0a6b6d 100%)`,
            },
            background: `linear-gradient(135deg, ${TEAL} 0%, #0c7a7c 100%)`,
            border: 'none',
            borderRadius: '8px',
            color: '#fff',
            fontSize: 13,
            fontWeight: 700,
            height: 38,
          }}
          variant="contained"
        >
          {!paymentStatus ? 'Pay' : 'Finish'}
        </Button>
      </Box>

      {/* ── Hidden print area ─────────────────────────────────────── */}
      <div style={{ display: 'none' }}>
        <PreOrderInvoice
          fontSize={calculateFontSize(printPaperSizeInPixel).fontSize}
          fontWeight={calculateFontSize(printPaperSizeInPixel).fontWeight}
          label={calculateFontSize(printPaperSizeInPixel).label}
          ref={componentRef}
          salesRes={invoiceData}
          width={printPaperSizeInPixel}
        />
      </div>

      {/* ── Modals ────────────────────────────────────────────────── */}
      <OrderCustomerModal
        defaultDeliveryDate={salesDetails.deliveryDateTime}
        onClose={() => setOpenAddMobile(false)}
        open={openAddMobile}
      />
      {openDiscount && (
        <SalesDiscount
          handleCloseDialog={() => setOpenDiscount(false)}
          openModel={openDiscount}
          title="Add Discount"
        />
      )}
      {openEditPopup && selectedItem && (
        <Kgpopup
          editGoldData={{
            goldCarrot: selectedItem.goldCarrot || '22K',
            goldPrice8g: selectedItem.goldPrice8g || 0,
            goldWasteQty: selectedItem.goldWasteQty || 0,
            goldWeightQty: selectedItem.goldWeightQty || 0,
            makingCharge: selectedItem.makingCharge || 0,
          }}
          handleAdd={handleEditAdd}
          handleCloseAlert={() => {
            setOpenEditPopup(false);
            setSelectedItem(null);
          }}
          open={openEditPopup}
          product={selectedItem}
        />
      )}
    </Box>
  );
};

export default React.memo(OrderLeftPanel);
